def count_correct(links, labels, t):
    right = 0
    for i in range(len(links)):
        if (links[i] >= t) == (labels[i] == 1):
            right = right + 1
    return right

def best_threshold(links, labels, ts):
    best = None
    best_right = -1
    for t in sorted(ts):
        right = count_correct(links, labels, t)
        if right > best_right:
            best = t
            best_right = right
    return best
